      font-size: 1.1rem;
      letter-spacing: -0.035em;
    }

    .price-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-top: 2px;
    }

    .price {
      font-weight: 900;
      font-size: 1.08rem;
    }

    .old-price {
      margin-left: 6px;
      color: #797483;
      text-decoration: line-through;
      font-size: 0.86rem;
      font-weight: 600;
    }

    .quick-add {
