    .quick-add:hover,
    .quick-add.added {
      color: #120f08;
      background: var(--gold);
    }

    .deals-layout {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 18px;
    }

    .deal-card {
      position: relative;
      min-height: 430px;
      border-radius: var(--radius);
      overflow: hidden;
    }

    .deal-main {
      padding: 34px;
      background:
        linear-gradient(90deg, rgba(8, 9, 13, 0.96) 0%, rgba(8, 9, 13, 0.6) 46%, rgba(8, 9, 13, 0.16)),
