      font-size: 0.72rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .deal-stack {
      display: grid;
      gap: 18px;
    }

    .mini-deal {
      min-height: 206px;
      padding: 24px;
      background:
        linear-gradient(145deg, rgba(24, 27, 38, 0.94), rgba(24, 27, 38, 0.58)),
