    }

    .discount {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: var(--green);
      font-weight: 900;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr 0.8fr;
      gap: 18px;
    }

    .article-card {
      border-radius: var(--radius);
      overflow: hidden;
    }

    .article-card.featured {
      grid-row: span 2;
    }

    .article-media {
      min-height: 230px;
      background: #1c1d25;
      overflow: hidden;
    }

    .article-card.featured .article-media {
      min-height: 460px;
    }

    .article-media img {
      display: block;
      width: 100%;
      height: 100%;
      min-height: inherit;
      object-fit: cover;
      transition: transform 220ms ease;
    }

    .article-card:hover img {
      transform: scale(1.05);
    }

    .article-content {
      padding: 22px;
    }

    .article-content span {
      color: var(--gold);
      font-size: 0.76rem;
      font-weight: 900;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .article-content h3 {
      margin: 10px 0;
      font-size: 1.45rem;
      line-height: 1.08;
      letter-spacing: -0.05em;
    }

    .article-card.featured h3 {
      font-size: clamp(1.8rem, 3vw, 2.75rem);
    }

    .article-content p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .newsletter {
