    .newsletter h2 {
      margin: 0 0 8px;
      font-size: clamp(1.8rem, 3vw, 3rem);
      letter-spacing: -0.06em;
    }

    .newsletter p {
      margin: 0;
      color: var(--muted);
      line-height: 1.7;
    }

    .newsletter-form {
      display: flex;
      align-items: center;
      min-width: min(460px, 100%);
      padding: 6px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.055);
    }

    .newsletter-form input {
      width: 100%;
      min-width: 0;
      border: 0;
      outline: 0;
      color: var(--text);
      background: transparent;
      padding: 0 14px;
      font: inherit;
    }

    .newsletter-form input::placeholder {
      color: #7d7788;
    }

    .site-footer {
      border-top: 1px solid var(--line);
      padding: 30px 0;
      color: var(--muted);
    }

    .footer-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      font-size: 0.92rem;
    }

    .footer-links {
      display: flex;
      gap: 18px;
    }

    .toast {
      position: fixed;
      right: 20px;
      bottom: 20px;
      z-index: 40;
      display: grid;
      gap: 3px;
      min-width: min(340px, calc(100% - 40px));
      padding: 16px 18px;
      border: 1px solid rgba(244, 199, 102, 0.22);
      border-radius: 18px;
      color: var(--text);
      background: rgba(17, 19, 26, 0.94);
      box-shadow: var(--shadow);
      opacity: 0;
      transform: translateY(18px);
      pointer-events: none;
      transition: opacity 180ms ease, transform 180ms ease;
      backdrop-filter: blur(18px);
    }

    .toast.visible {
      opacity: 1;
      transform: translateY(0);
    }

    .toast strong {
      color: var(--gold);
    }

    @media (max-width: 1020px) {
      .hero-grid,
      .deals-layout,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .hero-card {
        min-height: 520px;
      }

      .product-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .editorial-grid {
        grid-template-columns: 1fr 1fr;
      }

      .article-card.featured {
        grid-column: span 2;
      }

      .newsletter-form {
        min-width: 0;
      }
    }

    @media (max-width: 760px) {
      .container {
        width: min(100% - 28px, 1180px);
      }

      .nav {
        min-height: 68px;
      }

      .menu-toggle {
        display: inline-grid;
      }

      .nav-links {
        position: fixed;
        inset: 68px 14px auto;
        display: grid;
        gap: 4px;
        padding: 14px;
        border: 1px solid var(--line);
        border-radius: 22px;
        background: rgba(17, 19, 26, 0.96);
        box-shadow: var(--shadow);
        opacity: 0;
        transform: translateY(-10px);
        pointer-events: none;
        transition: opacity 160ms ease, transform 160ms ease;
      }

      .nav-links.open {
        opacity: 1;
        transform: translateY(0);
        pointer-events: auto;
      }

      .nav-links a {
        padding: 13px 14px;
        border-radius: 14px;
      }

      .nav-links a:hover {
        background: rgba(255, 255, 255, 0.06);
      }

      .hero {
        padding-top: 54px;
      }

      .hero h1 {
        font-size: clamp(3.05rem, 17vw, 5.3rem);
      }

      .stats,
      .product-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .section-header {
        display: grid;
      }

      .hero-card,
      .deal-card {
        min-height: 450px;
      }

      .showcase,
      .deal-main {
        padding: 24px;
      }

      .article-card.featured {
        grid-column: auto;
      }

      .article-card.featured .article-media {
        min-height: 290px;
      }

      .newsletter-form {
        display: grid;
        gap: 10px;
        border-radius: 22px;
      }

      .newsletter-form input {
        min-height: 42px;
      }

      .newsletter-form .button {
        width: 100%;
      }

      .footer-row {
        display: grid;
      }
    }
  </style>
</head>
