      showToast("Welcome to Noir", `${email} is on the early access list.`);
    });

    const dealEnd = Date.now() + (2 * 24 * 60 * 60 * 1000) + (11 * 60 * 60 * 1000) + (42 * 60 * 1000);
    const timeParts = {
