  <script>
    const menuToggle = document.querySelector("#menuToggle");
    const navLinks = document.querySelector("#navLinks");
    const chips = document.querySelectorAll(".chip");
    const products = document.querySelectorAll(".product-card");
    const quickAddButtons = document.querySelectorAll(".quick-add");
    const cartCount = document.querySelector("#cartCount");
    const toast = document.querySelector("#toast");
    const newsletterForm = document.querySelector("#newsletterForm");
    let cartItems = 0;
    let toastTimer;

    function showToast(title, message) {
      clearTimeout(toastTimer);
      toast.innerHTML = `<strong>${title}</strong><span>${message}</span>`;
      toast.classList.add("visible");
      toastTimer = setTimeout(() => toast.classList.remove("visible"), 2600);
    }

    menuToggle.addEventListener("click", () => {
      const isOpen = navLinks.classList.toggle("open");
      document.body.classList.toggle("menu-open", isOpen);
      menuToggle.setAttribute("aria-expanded", String(isOpen));
      menuToggle.setAttribute("aria-label", isOpen ? "Close menu" : "Open menu");
    });

    navLinks.addEventListener("click", (event) => {
      if (event.target.tagName !== "A") return;
      navLinks.classList.remove("open");
      document.body.classList.remove("menu-open");
      menuToggle.setAttribute("aria-expanded", "false");
      menuToggle.setAttribute("aria-label", "Open menu");
    });

    chips.forEach((chip) => {
      chip.addEventListener("click", () => {
        const filter = chip.dataset.filter;
        chips.forEach((item) => item.classList.toggle("active", item === chip));
        products.forEach((product) => {
          product.hidden = filter !== "all" && product.dataset.category !== filter;
        });
      });
    });

    quickAddButtons.forEach((button) => {
      button.addEventListener("click", () => {
        cartItems += 1;
        cartCount.textContent = cartItems;
        button.classList.add("added");
        button.textContent = "Added";
        setTimeout(() => {
          button.classList.remove("added");
          button.textContent = "Add";
        }, 1300);
        showToast("Added to bag", `${button.dataset.product} is ready for checkout.`);
      });
    });

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();
      const email = new FormData(newsletterForm).get("email") || newsletterForm.querySelector("input").value;
      newsletterForm.reset();
      showToast("Welcome to Noir", `${email} is on the early access list.`);
    });

    const dealEnd = Date.now() + (2 * 24 * 60 * 60 * 1000) + (11 * 60 * 60 * 1000) + (42 * 60 * 1000);
    const timeParts = {
      days: document.querySelector("#days"),
      hours: document.querySelector("#hours"),
      minutes: document.querySelector("#minutes"),
      seconds: document.querySelector("#seconds")
    };

    function updateCountdown() {
      const remaining = Math.max(0, dealEnd - Date.now());
      const totalSeconds = Math.floor(remaining / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;
      timeParts.days.textContent = String(days).padStart(2, "0");
      timeParts.hours.textContent = String(hours).padStart(2, "0");
      timeParts.minutes.textContent = String(minutes).padStart(2, "0");
      timeParts.seconds.textContent = String(seconds).padStart(2, "0");
    }

    updateCountdown();
    setInterval(updateCountdown, 1000);
  </script>
