      background: linear-gradient(135deg, var(--gold), #ffe8ad);
      box-shadow: 0 18px 46px rgba(244, 199, 102, 0.22);
    }

    .button-secondary {
      color: var(--text);
      border-color: var(--line);
      background: rgba(255, 255, 255, 0.045);
    }

    .hero-card {
      position: relative;
      min-height: 610px;
      padding: 22px;
      border: 1px solid var(--line);
      border-radius: 40px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.11), rgba(255, 255, 255, 0.025)),
        rgba(16, 18, 25, 0.7);
      box-shadow: var(--shadow);
      overflow: hidden;
      isolation: isolate;
    }

    .hero-card::before {
      content: "";
      position: absolute;
      inset: 12% -18% -16% 18%;
      z-index: -1;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(244, 199, 102, 0.28), transparent 60%);
      filter: blur(12px);
    }

    .showcase {
      position: absolute;
      inset: 22px;
      display: grid;
      align-content: end;
      padding: 30px;
      border-radius: 30px;
      background:
        linear-gradient(180deg, transparent 28%, rgba(0, 0, 0, 0.76)),
        url("https://images.unsplash.com/photo-1556228578-8c89e6adf883?auto=format&fit=crop&w=1000&q=80") center/cover;
      overflow: hidden;
    }

    .showcase-badge {
      position: absolute;
      top: 24px;
      right: 24px;
      padding: 10px 14px;
      border: 1px solid rgba(255, 255, 255, 0.18);
      border-radius: 999px;
      background: rgba(8, 9, 13, 0.62);
      backdrop-filter: blur(16px);
      font-size: 0.82rem;
      font-weight: 800;
    }

    .showcase h2 {
      margin: 0 0 10px;
      max-width: 430px;
      font-size: clamp(2rem, 4vw, 3.5rem);
      line-height: 0.95;
      letter-spacing: -0.06em;
    }

    .showcase p {
      max-width: 410px;
      margin: 0;
      color: #d8d1c4;
      line-height: 1.6;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
      margin-top: 44px;
    }

    .stat {
      padding: 22px;
      border: 1px solid var(--line);
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.045);
    }

    .stat strong {
      display: block;
      font-size: 1.55rem;
      letter-spacing: -0.04em;
    }

    .stat span {
      display: block;
      margin-top: 4px;
      color: var(--muted);
      font-size: 0.88rem;
    }

    .section {
      padding: 58px 0;
    }

    .section-header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 24px;
    }

    .section-kicker {
      color: var(--gold);
      font-size: 0.78rem;
      font-weight: 900;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .section-title {
      margin: 8px 0 0;
      font-size: clamp(2rem, 4vw, 3.55rem);
      line-height: 0.95;
      letter-spacing: -0.065em;
    }

    .section-copy {
      max-width: 430px;
      margin: 0;
      color: var(--muted);
      line-height: 1.7;
    }

    .category-row {
      display: flex;
      gap: 10px;
      margin: 26px 0 24px;
      overflow-x: auto;
      scrollbar-width: none;
    }

    .category-row::-webkit-scrollbar {
      display: none;
    }

    .chip {
      flex: 0 0 auto;
      padding: 11px 16px;
      border: 1px solid var(--line);
      border-radius: 999px;
      color: var(--muted);
      background: rgba(255, 255, 255, 0.035);
      cursor: pointer;
      transition: color 160ms ease, border-color 160ms ease, background 160ms ease;
    }

    .chip.active,
    .chip:hover {
      color: #14100a;
      border-color: transparent;
      background: var(--gold);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .product-card,
    .deal-card,
    .article-card,
    .newsletter {
      border: 1px solid var(--line);
      background: var(--panel);
      box-shadow: 0 16px 46px rgba(0, 0, 0, 0.18);
    }

    .product-card {
      position: relative;
      display: flex;
      flex-direction: column;
      min-height: 100%;
      border-radius: 24px;
      overflow: hidden;
    }

    .product-image {
      position: relative;
      min-height: 260px;
      background: var(--panel-strong);
      overflow: hidden;
    }

    .product-image img {
      width: 100%;
      height: 260px;
      object-fit: cover;
      display: block;
      transform: scale(1.01);
      transition: transform 220ms ease, filter 220ms ease;
    }

    .product-card:hover img {
      transform: scale(1.06);
      filter: saturate(1.12);
    }

    .tag {
      position: absolute;
      top: 14px;
      left: 14px;
      padding: 7px 10px;
      border-radius: 999px;
      color: #0e0b07;
      background: var(--gold);
      font-size: 0.72rem;
      font-weight: 900;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .tag.sale {
      background: var(--coral);
    }

    .product-info {
      display: grid;
      gap: 10px;
      padding: 18px;
    }

    .product-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      color: var(--muted);
      font-size: 0.86rem;
    }

    .product-info h3 {
      margin: 0;
      font-size: 1.1rem;
      letter-spacing: -0.035em;
    }

    .price-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-top: 2px;
    }

    .price {
      font-weight: 900;
      font-size: 1.08rem;
    }

    .old-price {
      margin-left: 6px;
      color: #797483;
      text-decoration: line-through;
      font-size: 0.86rem;
      font-weight: 600;
    }

    .quick-add {
      border: 1px solid rgba(244, 199, 102, 0.32);
      border-radius: 999px;
      color: var(--gold);
      background: rgba(244, 199, 102, 0.08);
      padding: 9px 12px;
      cursor: pointer;
      font-weight: 800;
      transition: background 160ms ease, color 160ms ease;
    }

    .quick-add:hover,
    .quick-add.added {
      color: #120f08;
      background: var(--gold);
    }

    .deals-layout {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 18px;
    }

    .deal-card {
      position: relative;
      min-height: 430px;
      border-radius: var(--radius);
      overflow: hidden;
    }

    .deal-main {
      padding: 34px;
      background:
        linear-gradient(90deg, rgba(8, 9, 13, 0.96) 0%, rgba(8, 9, 13, 0.6) 46%, rgba(8, 9, 13, 0.16)),
        url("https://images.unsplash.com/photo-1556905055-8f358a7a47b2?auto=format&fit=crop&w=1200&q=80") center/cover;
    }

    .deal-card h3 {
      margin: 12px 0 12px;
      max-width: 520px;
      font-size: clamp(2.1rem, 4vw, 4rem);
      line-height: 0.94;
      letter-spacing: -0.07em;
    }

    .deal-card p {
      max-width: 430px;
      color: var(--muted);
      line-height: 1.7;
    }

    .countdown {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin: 28px 0;
    }

    .time-box {
      min-width: 78px;
      padding: 14px 12px;
      border: 1px solid var(--line);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.08);
      text-align: center;
    }

    .time-box strong {
      display: block;
      font-size: 1.6rem;
      letter-spacing: -0.04em;
    }

    .time-box span {
      color: var(--muted);
      font-size: 0.72rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .deal-stack {
      display: grid;
      gap: 18px;
    }

    .mini-deal {
      min-height: 206px;
      padding: 24px;
      background:
        linear-gradient(145deg, rgba(24, 27, 38, 0.94), rgba(24, 27, 38, 0.58)),
        radial-gradient(circle at 100% 0%, rgba(244, 199, 102, 0.22), transparent 18rem);
    }

    .mini-deal h4 {
      margin: 10px 0;
      font-size: 1.65rem;
      line-height: 1;
      letter-spacing: -0.055em;
    }

    .mini-deal p {
      margin-bottom: 0;
    }

    .discount {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: var(--green);
      font-weight: 900;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr 0.8fr;
      gap: 18px;
    }

    .article-card {
      border-radius: var(--radius);
      overflow: hidden;
    }

    .article-card.featured {
      grid-row: span 2;
    }

    .article-media {
      min-height: 230px;
      background: #1c1d25;
      overflow: hidden;
    }

    .article-card.featured .article-media {
      min-height: 460px;
    }

    .article-media img {
      display: block;
      width: 100%;
      height: 100%;
      min-height: inherit;
      object-fit: cover;
      transition: transform 220ms ease;
    }

    .article-card:hover img {
      transform: scale(1.05);
    }

    .article-content {
      padding: 22px;
    }

    .article-content span {
      color: var(--gold);
      font-size: 0.76rem;
      font-weight: 900;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .article-content h3 {
      margin: 10px 0;
      font-size: 1.45rem;
      line-height: 1.08;
      letter-spacing: -0.05em;
    }

    .article-card.featured h3 {
      font-size: clamp(1.8rem, 3vw, 2.75rem);
    }

    .article-content p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .newsletter {
      display: grid;
      grid-template-columns: 1fr auto;
      align-items: center;
      gap: 24px;
      margin: 46px 0 72px;
      padding: 28px;
      border-radius: var(--radius);
      background:
        radial-gradient(circle at 82% 20%, rgba(244, 199, 102, 0.16), transparent 18rem),
        var(--panel);
    }

    .newsletter h2 {
      margin: 0 0 8px;
      font-size: clamp(1.8rem, 3vw, 3rem);
      letter-spacing: -0.06em;
    }

    .newsletter p {
      margin: 0;
      color: var(--muted);
      line-height: 1.7;
    }

    .newsletter-form {
      display: flex;
      align-items: center;
      min-width: min(460px, 100%);
      padding: 6px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.055);
    }

    .newsletter-form input {
      width: 100%;
      min-width: 0;
      border: 0;
      outline: 0;
      color: var(--text);
      background: transparent;
      padding: 0 14px;
      font: inherit;
    }

    .newsletter-form input::placeholder {
      color: #7d7788;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .site-footer {
      border-top: 1px solid var(--line);
      padding: 30px 0;
      color: var(--muted);
    }

    .footer-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      font-size: 0.92rem;
    }

    .footer-links {
      display: flex;
      gap: 18px;
    }

    .toast {
      position: fixed;
      right: 20px;
      bottom: 20px;
      z-index: 40;
      display: grid;
      gap: 3px;
      min-width: min(340px, calc(100% - 40px));
      padding: 16px 18px;
      border: 1px solid rgba(244, 199, 102, 0.22);
      border-radius: 18px;
      color: var(--text);
      background: rgba(17, 19, 26, 0.94);
      box-shadow: var(--shadow);
      opacity: 0;
      transform: translateY(18px);
      pointer-events: none;
      transition: opacity 180ms ease, transform 180ms ease;
      backdrop-filter: blur(18px);
    }

    .toast.visible {
      opacity: 1;
      transform: translateY(0);
    }

    .toast strong {
      color: var(--gold);
    }

    @media (max-width: 1020px) {
      .hero-grid,
      .deals-layout,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .hero-card {
        min-height: 520px;
      }

      .product-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .editorial-grid {
        grid-template-columns: 1fr 1fr;
      }

      .article-card.featured {
        grid-column: span 2;
      }

      .newsletter-form {
        min-width: 0;
      }
    }

    @media (max-width: 760px) {
      .container {
        width: min(100% - 28px, 1180px);
      }

      .nav {
        min-height: 68px;
      }

      .menu-toggle {
        display: inline-grid;
      }

      .nav-links {
        position: fixed;
        inset: 68px 14px auto;
        display: grid;
        gap: 4px;
        padding: 14px;
        border: 1px solid var(--line);
        border-radius: 22px;
        background: rgba(17, 19, 26, 0.96);
        box-shadow: var(--shadow);
        opacity: 0;
        transform: translateY(-10px);
        pointer-events: none;
        transition: opacity 160ms ease, transform 160ms ease;
      }

      .nav-links.open {
        opacity: 1;
        transform: translateY(0);
        pointer-events: auto;
      }

      .nav-links a {
        padding: 13px 14px;
        border-radius: 14px;
      }

      .nav-links a:hover {
        background: rgba(255, 255, 255, 0.06);
      }

      .hero {
        padding-top: 54px;
      }

      .hero h1 {
        font-size: clamp(3.05rem, 17vw, 5.3rem);
      }

      .stats,
      .product-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .section-header {
        display: grid;
      }

      .hero-card,
      .deal-card {
        min-height: 450px;
      }

      .showcase,
      .deal-main {
        padding: 24px;
      }

      .article-card.featured {
        grid-column: auto;
      }

      .article-card.featured .article-media {
        min-height: 290px;
      }

      .newsletter-form {
        display: grid;
        gap: 10px;
        border-radius: 22px;
      }

      .newsletter-form input {
        min-height: 42px;
      }

      .newsletter-form .button {
        width: 100%;
      }

      .footer-row {
        display: grid;
      }
    }
  </style>
</head>
<body>
